#!/usr/bin/env bash
# deploy_finans_oda_v6.sh — BU AY marji KANON kaynaga bagli: v_marj_cari_ay (akis maliyeti, cari ay canli view).
#   V5 son-bilinen birim_maliyet carry-forward TAHMINIYDI. V6 ana atom fonksiyonuyla AYNI akis yontemini cari aya uygular.
#   -> Finans "bu ay" marji = KANON. (Kokpit "bu ay" ayni view'a AYRI adimda baglanacak; bu deploy yalniz finansi tasir.)
#   * /api/bi/finans/oda   -> V5 -> V6 (pencere.buay.marj = v_marj_cari_ay) YERINDE degistirilir
#   * shells/finans.html   -> Bu ay etiketi "kismi ay - kanon akis maliyeti - %X kapsam"
# ONKOSUL: v_marj_cari_ay CANLI olmali (kanon_cari_ay_view.sql calistirilmis olmali).
# SUNUCUDA:  cd /opt/krb-assessment && bash deploy_finans_oda_v6.sh
# node --check + canli DB-hakikat + COKME kontrolu + OTOMATIK ROLLBACK. Yedek: *.bak_odav6_<ts>
# NOT: server_container.mjs PAYLASILAN — calistirmadan once paralel deploy AKISTA OLMADIGINI dogrula.
set -euo pipefail
TS=$(date +%Y%m%d_%H%M%S)
T='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa'

echo "== [0] onkosul: v_marj_cari_ay canli mi? =="
VOK=$(docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -tAc "SELECT count(*) FROM pg_views WHERE viewname='v_marj_cari_ay';")
if [ "$VOK" != "1" ]; then echo "  !!! v_marj_cari_ay YOK — once kanon_cari_ay_view.sql calistir. DURDU."; exit 1; fi
echo "  v_marj_cari_ay: var"

echo "== [1] finans.html yaz =="
cp shells/finans.html "finans.html.bak_odav6_$TS" 2>/dev/null || true
base64 -d > shells/finans.html <<'B64_FIN'
